// =====================================================
// ПЛАВНОЕ ДВИЖЕНИЕ СЕРВОПРИВОДА
// =====================================================

void moveServoSmoothly(int startAngle, int endAngle) {

  // Движение вперёд: 0° → 90°
  if (startAngle < endAngle) {

    for (int angle = startAngle; angle <= endAngle; angle++) {

      doorServo.write(angle);

      delay(SERVO_STEP_DELAY);
    }
  }


  // Движение назад: 90° → 0°
  else {

    for (int angle = startAngle; angle >= endAngle; angle--) {

      doorServo.write(angle);

      delay(SERVO_STEP_DELAY);
    }
  }
}


// =====================================================
// ОТКРЫТИЕ / ЗАКРЫТИЕ ДВЕРЦЫ
// =====================================================

void toggleDoor() {

  // ---------------------------------------------------
  // ЕСЛИ ДВЕРЦА ЗАКРЫТА
  // ---------------------------------------------------

  if (doorOpen == false) {

    Serial.println("Открываем дверцу...");
    Serial.println("Плавное движение: 0 -> 90 градусов");

    // Плавно открываем дверцу
    moveServoSmoothly(
      DOOR_CLOSED_ANGLE,
      DOOR_OPEN_ANGLE
    );

    // Запоминаем новое состояние
    doorOpen = true;

    Serial.println("Дверца открыта.");
  }


  // ---------------------------------------------------
  // ЕСЛИ ДВЕРЦА ОТКРЫТА
  // ---------------------------------------------------

  else {

    Serial.println("Закрываем дверцу...");
    Serial.println("Плавное движение: 90 -> 0 градусов");

    // Плавно закрываем дверцу
    moveServoSmoothly(
      DOOR_OPEN_ANGLE,
      DOOR_CLOSED_ANGLE
    );

    // Запоминаем новое состояние
    doorOpen = false;

    Serial.println("Дверца закрыта.");
  }
}
